var root=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Prefabs/Character.prefab");
try{
 var rig=root.GetComponent<Character.Control.PaddleCharacterVisual>();float error=0,minGap=100,maxLengthError=0;
 foreach(float g in new[]{.65f,1f,1.5f})foreach(float reach in new[]{.75f,1.05f,1.975f})for(int i=0;i<360;i++){
  var q=UnityEngine.Quaternion.Euler(0,0,i);rig.body.localScale=UnityEngine.Vector3.one*7.5f*g;rig.tool.localScale=UnityEngine.Vector3.one*g;
  rig.tool.rotation=q;rig.tool.position=rig.body.position+q*new UnityEngine.Vector3(reach*g,.074f*g,0);rig.Pose();
  error=UnityEngine.Mathf.Max(error,rig.HandError);minGap=UnityEngine.Mathf.Min(minGap,UnityEngine.Vector3.Distance(rig.LeftHand,rig.RightHand)/g);
  maxLengthError=UnityEngine.Mathf.Max(maxLengthError,UnityEngine.Mathf.Abs(UnityEngine.Vector3.Distance(rig.LeftHand,rig.LeftElbow)/g-.49f),UnityEngine.Mathf.Abs(UnityEngine.Vector3.Distance(rig.RightHand,rig.RightElbow)/g-.49f));
 }
 string log="3240 poses: wrist error="+error+"; min hand separation/scale="+minGap+"; max fixed .49m forearm length deviation="+maxLengthError;
 System.IO.File.WriteAllText("scripts/player-proportions-20261111/range.txt",log);UnityEngine.Debug.Log(log);
 if(error>.001f||minGap<.12f||maxLengthError>.001f)throw new System.Exception("Natural arm reach regression");
}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}
